contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function test(address _nonOwner, address _recipient, uint256 _amount) public {
        require(address(this).balance >= _amount);

        // fund c through its payable fallback (top-level state-changing call)
        bool funded;
        (funded, ) = address(c).call{value: _amount}("");
        require(funded);

        uint256 balanceBefore = address(c).balance;

        // a non-owner attempts to withdraw everything
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.withdrawAll.selector, _recipient)
        );

        // The call must revert, and c must not have lost its funds.
        assert(!ok && address(c).balance == balanceBefore);
    }
}

