        // burn far more than the 2300 gas stipend given by transfer
        r1 = 1;
        r2 = 2;
        r3 = 3;
    }

    function f(uint256 amount) public payable {
        require(address(this).balance >= amount);
        // fund c through its payable fallback
        (bool sf, ) = address(c).call{value: amount}("");
        require(sf);
        // withdrawAll to this gas-hungry receiver; observe via revert boolean
        bool ok;
        (ok, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", address(this)));
        assert(!ok);
    }
}

